"""Membership value built from approved BBLO prices, activities and real media."""
from pathlib import Path
import runpy,re
REPO=Path(__file__).resolve().parents[1]
n=runpy.run_path(str(REPO/'scripts/build-community-intake.py'))
sec,page=n['sec'],n['page'];B='/website-preview'
body=sec('<p class="eyebrow">BBLO membership · Ocala &amp; Marion County</p><h1>Show up for your business.<br><em>Build something together.</em></h1><p class="lead">Business workshops. Practical training. Local relationships. Community involvement. BBLO brings the people and opportunities into one ongoing business community—so you can spend more time participating and putting what you learn to work.</p><p><strong>We build businesses. Not just connections.</strong></p><div class="email-actions"><a class="button" href="#membership-price">See membership options</a><a class="button secondary" href="'+B+'/bblo/join/">Plan your first visit</a></div>','hero')
benefits=[('Business workshops &amp; training','Build practical business knowledge through scheduled workshops, presentations, training and conversations with other owners. Bring questions and look for actions you can use in your business.'),('Relationships that keep growing','Meet regularly, learn what other businesses do and help people understand who you serve. Familiarity gives introductions and follow-up a stronger foundation.'),('Visibility with a human connection','Introduce your business, get to know the people behind other local businesses and participate in member spotlight opportunities. Your involvement gives others more context when an opportunity comes up.'),('Community engagement','Learn directly from local nonprofits, participate in community activities and discover where your time, resources and connections can make a difference.'),('Field trips &amp; firsthand learning','Step outside the usual meeting room through scheduled Field Trip Fridays and local business visits. See how other businesses and community organizations work.'),('A private member hub','Approved BBLO members have a place for webinar and event updates, photos, videos, member resources and announcements after signing in.'),('Member partner offers','Explore current C-Suiteware and Media Minds member offers. Confirm eligibility, scope and current pricing through BBLO before purchasing; these services have their own charges.'),('English &amp; Spanish connections','Build relationships across language and business backgrounds. You do not have to speak Spanish to participate.')]
body+=sec('<p class="eyebrow">What your membership brings together</p><h2>More ways to learn.<br>More reasons to connect.</h2><div class="grid two">'+''.join('<article class="card"><h3>'+a+'</h3><p>'+b+'</p></article>' for a,b in benefits)+'</div><p>Programs, topics, presenters and visit locations follow the published schedule. Check each activity’s details for availability and any separate registration cost.</p>')
body+=sec('<p class="eyebrow">See the participation behind the promise</p><h2>This is what showing up looks like.</h2><figure style="margin:24px 0"><img src="/website-preview/assets/curated-bblo/20260828/20260828_103010.webp" alt="BBLO participants together at Media Minds" width="1400" height="1050" loading="lazy" decoding="async" style="display:block;width:100%;height:auto;max-height:360px;object-fit:contain;background:#0b1f3a"></figure><div class="grid three">'+''.join('<a class="card connection-card" href="'+B+u+'"><h3>'+t+'</h3><p>'+d+'</p><span class="text-link">See the activity →</span></a>' for u,t,d in [('/bblo/community-impact/habitat-vet-build/','Working alongside Habitat','BBLO participated in a Vet Build, connecting business owners through shared work and community involvement.'),('/bblo/community-impact/emergency-management-tour/','Learning before an emergency','A visit to Marion County Emergency Management opened a conversation about preparedness and community resources.'),('/bblo/community-impact/community-nonprofit-spotlights/','Meeting the missions','The Rock Program and Champions for Champions came to BBLO to introduce their work and the needs they serve.')])+'</div><div class="email-actions"><a class="button secondary" href="'+B+'/bblo/gallery/">See BBLO in Action</a><a class="button secondary" href="'+B+'/bblo/members/">Meet our member businesses</a></div>')
body+=sec('<div id="membership-price"><p class="eyebrow">Your membership investment</p><h2>Make room for your business to grow.</h2><div class="grid three"><article class="card"><h3>Monthly membership</h3><p class="lead"><strong>$40 / month</strong></p><p>Recurring on the 1st. A flexible way to make ongoing participation part of your business routine.</p><p>$65 non-refundable application fee. Application plus one month: $105.</p></article><article class="card"><h3>Annual single membership</h3><p class="lead"><strong>$450 / year</strong></p><p>Equivalent to $37.50 per month. Save $30 compared with twelve $40 monthly payments.</p><p>$65 non-refundable application fee. Application plus annual single membership: $515.</p></article><article class="card"><h3>Annual dual membership</h3><p class="lead"><strong>$600 / year</strong></p><p>Ask BBLO which dual-membership arrangement fits your business and confirm the applicable application requirements.</p></article></div><p><strong>Your first two visits are free.</strong> Drop-ins after those visits are $20 each. Membership requires committee review and final approval; submitting an application or payment does not itself grant member access.</p></div>')
body+=sec('<p class="eyebrow">Put the value in perspective</p><h2>One community. An ongoing place to participate.</h2><div style="overflow-x:auto"><table><caption>Ways to access business connections and learning</caption><thead><tr><th scope="col">What you want</th><th scope="col">Arrange it separately</th><th scope="col">Through BBLO</th></tr></thead><tbody><tr><th scope="row">Four BBLO meetings as paid drop-ins</th><td>$20 × 4 = $80, after the two free visits</td><td>$40 monthly membership: $40 less in a four-meeting comparison</td></tr><tr><th scope="row">A year of single membership</th><td>Twelve monthly payments: $480</td><td>Annual single plan: $450, a $30 saving</td></tr><tr><th scope="row">Workshops and training</th><td>Find individual programs, register and build your own schedule. Some resources are free; paid programs vary.</td><td>Scheduled business learning within a community where you can discuss it and keep connecting.</td></tr><tr><th scope="row">Local business relationships</th><td>Arrange separate meetings and keep each relationship moving yourself.</td><td>Regular group participation, introductions and opportunities to get to know members over time.</td></tr><tr><th scope="row">Community involvement</th><td>Find organizations, learn their needs and coordinate your participation.</td><td>Meet local missions and participate in scheduled group activities and visits.</td></tr><tr><th scope="row">Member updates and resources</th><td>Keep track of separate announcements and contacts.</td><td>A private member hub for BBLO updates, resources and shared media.</td></tr></tbody></table></div><p>The $65 application fee is additional. First-year single membership totals $545 when paid monthly, or $515 annually. The four-meeting comparison is an illustration using published BBLO rates, not a promise of four meetings every month. Special activities and partner services may have separate costs. This comparison does not assign invented retail prices to relationships, referrals or workshops.</p>')
body+=sec('<p class="eyebrow">Your part in the value</p><h2>Come ready to connect.<br>Leave with a reason to follow up.</h2><p>Bring your questions, share what you know, learn how to refer other businesses and make time for the next conversation. Participation creates the opportunity; relationships and results grow through consistent follow-through.</p><div class="grid three"><article class="card"><h3>Show up.</h3><p>Prepare your 30-second introduction and make it easy for people to understand who you help.</p></article><article class="card"><h3>Get involved.</h3><p>Join the conversations, scheduled learning and community activities that fit your goals.</p></article><article class="card"><h3>Keep connecting.</h3><p>Follow up, get to know another member and look for a useful introduction you can make.</p></article></div><p>Referrals, sales, revenue and presentation slots are not guaranteed. You are joining a business community with opportunities to participate.</p><div class="email-actions"><a class="button" href="'+B+'/bblo/join/">Visit BBLO &amp; take the next step</a><a class="button secondary" href="'+B+'/inquire/?service=bblo-membership">Ask about membership</a></div>')
page('/bblo/benefits/','BBLO Membership Benefits &amp; Pricing | Ocala Business Community | TLC','Explore BBLO membership: $40 monthly or $450 annual single, business learning, community engagement, local connections and member resources.',body)
# Link the new benefits page from join and hub without altering member profiles.
for r in ['bblo/join','bblo']:
 p=REPO/'website-preview'/r/'index.html';s=p.read_text();s=re.sub(r'<!-- benefits-discovery-start -->.*?<!-- benefits-discovery-end -->','',s,flags=re.S)
 c='<!-- benefits-discovery-start -->'+sec('<p class="eyebrow">Why join BBLO?</p><h2>See what your membership brings together.</h2><p>Explore the business learning, relationships, community involvement, member resources and pricing behind BBLO.</p><a class="button" href="'+B+'/bblo/benefits/">Membership benefits &amp; pricing</a>')+'<!-- benefits-discovery-end -->';s=s.replace('<section class="carmen-trail"',c+'<section class="carmen-trail"',1);p.write_text(s)
